1	//! The bundled templates (spec §11 G-44): every module of `tests/graphics/`
2	//! except road map 10's six fixtures draws without a warning, with no `NaN`
3	//! or `Infinity` in its SVG, and nothing outside the 90 % title-safe
4	//! rectangle moves — at 1920×1080, 1080×1920 and 1080×1080, every fifth
5	//! frame and the last, which every outro leaves bare. Every combination of
6	//! a template's `enum` options is held to the same through its entrance,
7	//! its hold and its last frame. `project.yml` copies exactly the folder's
8	//! modules.
9	//! `GRAPHIC_TEMPLATE_PNGS=<dir>` writes frames 12, D/2 and D−8 of each, over
10	//! opaque `#6e6e74`, for a person to look at.
11	
12	mod common;
13	
14	use std::fs;
15	use std::time::Instant;
16	
17	use graphic::{rasterize, Module};
18	use serde_json::Value;
19	
20	use common::{shared, BUDGET_MS, FIXTURES, GRAPHICS};
21	
22	const SIZES: [(u32, u32); 3] = [(1920, 1080), (1080, 1920), (1080, 1080)];
23	const FPS: f64 = 30.0;
24	
25	/// The template stems: the folder's `*.js` less the fixtures, sorted.
26	fn templates() -> Vec<String> {
27	    let mut stems: Vec<String> = fs::read_dir(GRAPHICS)
28	        .expect("tests/graphics")
29	        .map(|entry| entry.expect("a directory entry").path())
30	        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
31	        .map(|path| path.file_stem().unwrap().to_string_lossy().into_owned())
32	        .filter(|stem| !FIXTURES.contains(&stem.as_str()))
33	        .collect();
34	    stems.sort();
35	    assert!(!stems.is_empty(), "no template in {GRAPHICS}");
36	    stems
37	}
38	
39	fn duration(module: &Module) -> i64 {
40	    module.meta()["durationInFrames"]
41	        .as_i64()
42	        .expect("a template's meta.durationInFrames")
43	}
44	
45	/// One frame drawn: the BGRA, or every problem with it named.
46	fn draw(
47	    module: &Module,
48	    frame: i64,
49	    props: &Value,
50	    (width, height): (u32, u32),
51	) -> Result<Vec<u8>, String> {
52	    let name = module.name();
53	    let ctx = common::ctx(frame, FPS, duration(module), width, height);
54	    let at = format!("{name} {width}x{height} frame {frame}");
55	    let (svg, warnings) = graphic::svg(module, frame, props, &ctx, BUDGET_MS)
56	        .map_err(|d| format!("{at}: {}", d.message))?;
57	    if !warnings.is_empty() {
58	        return Err(format!(
59	            "{at}: svg warned {:?}",
60	            common::messages(&warnings)
61	        ));
62	    }
63	    for bad in ["NaN", "Infinity"] {
64	        if svg.contains(bad) {
65	            return Err(format!("{at}: the SVG holds {bad}"));
66	        }
67	    }
68	    let stride = width as usize * 4;
69	    let mut out = vec![0u8; stride * height as usize];
70	    let raster = rasterize(&shared(), &svg, width, height, &mut out, stride)
71	        .map_err(|d| format!("{at}: rasterize refused: {}", d.message))?;
72	    if !raster.is_empty() {
73	        return Err(format!(
74	            "{at}: rasterize warned {:?}",
75	            common::messages(&raster)
76	        ));
77	    }
78	    Ok(out)
79	}
80	
81	/// Whether pixel `(x, y)` is outside title-safe: x ∈ [0.05W, 0.95W),
82	/// y ∈ [0.05H, 0.95H).
83	fn outside(x: u32, y: u32, (width, height): (u32, u32)) -> bool {
84	    x < width * 5 / 100 || x >= width * 95 / 100 || y < height * 5 / 100 || y >= height * 95 / 100
85	}
86	
87	/// The first pixel outside title-safe where `a` and `b` differ.
88	fn first_difference(a: &[u8], b: &[u8], size: (u32, u32)) -> Option<(u32, u32)> {
89	    let (width, height) = size;
90	    for y in 0..height {
91	        for x in 0..width {
92	            let at = (y as usize * width as usize + x as usize) * 4;
93	            if outside(x, y, size) && a[at..at + 4] != b[at..at + 4] {
94	                return Some((x, y));
95	            }
96	        }
97	    }
98	    None
99	}
100	
101	/// Frame 0's alpha outside title-safe, when it is one value (0 or 255).
102	fn border_alpha(frame0: &[u8], size: (u32, u32)) -> Result<u8, String> {
103	    let (width, height) = size;
104	    let mut seen: Option<u8> = None;
105	    for y in 0..height {
106	        for x in 0..width {
107	            if !outside(x, y, size) {
108	                continue;
109	            }
110	            let alpha = frame0[(y as usize * width as usize + x as usize) * 4 + 3];
111	            match seen {
112	                None => seen = Some(alpha),
113	                Some(a) if a != alpha => {
114	                    return Err(format!(
115	                        "alpha {a} and {alpha} (at {x},{y}) outside title-safe"
116	                    ))
117	                }
118	                _ => {}
119	            }
120	        }
121	    }
122	    match seen {
123	        Some(a @ (0 | 255)) => Ok(a),
124	        other => Err(format!("alpha {other:?} outside title-safe, not 0 or 255")),
125	    }
126	}
127	
128	/// Writes `frame` of `module` at `size` over opaque `#6e6e74` as an RGB PNG.
129	fn dump(dir: &str, module: &Module, frame: i64, size: (u32, u32)) {
130	    let (width, height) = size;
131	    let bgra = draw(module, frame, &module.defaults(), size).unwrap_or_else(|e| panic!("{e}"));
132	    let grey = [0x6e_u32, 0x6e, 0x74];
133	    let rgb: Vec<u8> = bgra
134	        .chunks_exact(4)
135	        .flat_map(|p| {
136	            let under = 255 - p[3] as u32;
137	            let over = |src: u8, bg: u32| (src as u32 + (bg * under + 127) / 255).min(255) as u8;
138	            [
139	                over(p[2], grey[0]),
140	                over(p[1], grey[1]),
141	                over(p[0], grey[2]),
142	            ]
143	        })
144	        .collect();
145	    fs::create_dir_all(dir).expect("the PNG folder");
146	    let path = format!("{dir}/{}-{width}x{height}-{frame}.png", module.name());
147	    let file = fs::File::create(&path).expect("a PNG file");
148	    let mut encoder = png::Encoder::new(std::io::BufWriter::new(file), width, height);
149	    encoder.set_color(png::ColorType::Rgb);
150	    encoder.set_depth(png::BitDepth::Eight);
151	    let mut writer = encoder.write_header().expect("a PNG header");
152	    writer.write_image_data(&rgb).expect("PNG data");
153	}
154	
155	/// The frames sampled: 0, 5, 10, … and the last.
156	fn sampled(duration: i64) -> Vec<i64> {
157	    let mut frames: Vec<i64> = (0..duration).step_by(5).collect();
158	    if frames.last() != Some(&(duration - 1)) {
159	        frames.push(duration - 1);
160	    }
161	    frames
162	}
163	
164	/// The first pixel of the last frame that is not bare: for an overlay
165	/// (`border` 0) one with any alpha, for a card one that differs from the
166	/// background, frame 0's pixel (0, 0).
167	fn not_bare(last: &[u8], frame0: &[u8], border: u8, width: u32) -> Option<(u32, u32)> {
168	    let at = |i: usize| ((i % width as usize) as u32, (i / width as usize) as u32);
169	    last.chunks_exact(4)
170	        .position(|p| {
171	            if border == 0 {
172	                p[3] != 0
173	            } else {
174	                p != &frame0[..4]
175	            }
176	        })
177	        .map(at)
178	}
179	
180	/// Draws `frames` (frame 0 first) of `module` with `props` at `size` and
181	/// holds them to G-44 (b) and (c): frame 0 has one alpha outside title-safe
182	/// (0 or 255), no later frame differs from it there, and the last frame,
183	/// `D − 1`, when sampled, is bare (`not_bare`) — every outro fades all of
184	/// its content. A frame 0 that fails to draw skips the comparisons. Answers
185	/// each frame's svg+rasterize ms.
186	fn check(
187	    module: &Module,
188	    props: &Value,
189	    frames: &[i64],
190	    size: (u32, u32),
191	    what: &str,
192	    failures: &mut Vec<String>,
193	) -> Vec<f64> {
194	    let last = duration(module) - 1;
195	    let mut times = Vec::new();
196	    let mut base: Option<(Vec<u8>, u8)> = None;
197	    for &frame in frames {
198	        let started = Instant::now();
199	        let drawn = draw(module, frame, props, size);
200	        times.push(started.elapsed().as_secs_f64() * 1000.0);
201	        let bgra = match drawn {
202	            Ok(bgra) => bgra,
203	            Err(e) => {
204	                failures.push(format!("{what}: {e}"));
205	                continue;
206	            }
207	        };
208	        if frame == 0 {
209	            match border_alpha(&bgra, size) {
210	                Ok(alpha) => base = Some((bgra, alpha)),
211	                Err(e) => failures.push(format!("{what} {size:?} frame 0: {e}")),
212	            }
213	            continue;
214	        }
215	        let Some((first, alpha)) = &base else {
216	            continue;
217	        };
218	        if let Some((x, y)) = first_difference(first, &bgra, size) {
219	            failures.push(format!(
220	                "{what} {size:?} frame {frame}: pixel ({x}, {y}) outside title-safe differs from frame 0"
221	            ));
222	        }
223	        if frame == last {
224	            if let Some((x, y)) = not_bare(&bgra, first, *alpha, size.0) {
225	                failures.push(format!(
226	                    "{what} {size:?} last frame {frame}: pixel ({x}, {y}) is still drawn after the outro"
227	                ));
228	            }
229	        }
230	    }
231	    times
232	}
233	
234	#[test]
235	fn every_template_draws_cleanly_inside_title_safe() {
236	    let dump_dir = std::env::var("GRAPHIC_TEMPLATE_PNGS").ok();
237	    let mut failures = Vec::new();
238	    for stem in templates() {
239	        let module = common::module(&stem);
240	        let props = module.defaults();
241	        let d = duration(&module);
242	        for size in SIZES {
243	            let mut times = check(&module, &props, &sampled(d), size, &stem, &mut failures);
244	            if size == SIZES[0] {
245	                times.sort_by(|a, b| a.partial_cmp(b).unwrap());
246	                let p95 = times[((times.len() as f64 * 0.95).ceil() as usize).max(1) - 1];
247	                println!("{stem}: p95 svg+rasterize {p95:.2} ms at 1920x1080");
248	            }
249	            if let Some(dir) = &dump_dir {
250	                for frame in [12, d / 2, d - 8] {
251	                    dump(dir, &module, frame, size);
252	                }
253	            }
254	        }
255	    }
256	    assert!(failures.is_empty(), "{}", failures.join("\n"));
257	}
258	
259	/// Props at the schema's edges that the enum pass also draws: a window
260	/// frame filling title-safe, and one leaving its shadow a thin margin.
261	fn edges() -> Vec<(&'static str, Value)> {
262	    vec![
263	        ("window-frame", serde_json::json!({"scale": 1})),
264	        ("window-frame", serde_json::json!({"scale": 0.97})),
265	    ]
266	}
267	
268	/// Every combination of a template's `enum` options, the other props at
269	/// their defaults, plus `edges()`: each as `(what, props)`.
270	fn variants(stem: &str, module: &Module) -> Vec<(String, Value)> {
271	    let mut out = vec![(String::new(), module.defaults())];
272	    for (key, entry) in module.schema().as_object().expect("a schema object") {
273	        if entry["type"] != "enum" {
274	            continue;
275	        }
276	        let options = entry["options"].as_array().expect("an enum's options");
277	        out = out
278	            .iter()
279	            .flat_map(|(what, props)| {
280	                options.iter().map(move |option| {
281	                    let mut props = props.clone();
282	                    props[key] = option.clone();
283	                    (
284	                        format!("{what} {key}={}", option.as_str().unwrap_or("?")),
285	                        props,
286	                    )
287	                })
288	            })
289	            .collect();
290	    }
291	    for (_, overrides) in edges().into_iter().filter(|(s, _)| *s == stem) {
292	        let mut props = module.defaults();
293	        for (key, value) in overrides.as_object().unwrap() {
294	            props[key] = value.clone();
295	        }
296	        out.push((format!(" {overrides}"), props));
297	    }
298	    out.into_iter()
299	        .filter(|(what, _)| !what.is_empty())
300	        .map(|(what, props)| (format!("{stem}{what}"), props))
301	        .collect()
302	}
303	
304	#[test]
305	fn every_enum_option_draws_cleanly_inside_title_safe() {
306	    let mut failures = Vec::new();
307	    let mut drawn = 0;
308	    for stem in templates() {
309	        let module = common::module(&stem);
310	        let d = duration(&module);
311	        for (what, props) in variants(&stem, &module) {
312	            drawn += 1;
313	            for size in SIZES {
314	                let frames = [0, 3, 6, 9, 12, d / 2, d - 1];
315	                check(&module, &props, &frames, size, &what, &mut failures);
316	            }
317	        }
318	    }
319	    assert!(drawn > 0, "no template has an enum");
320	    assert!(failures.is_empty(), "{}", failures.join("\n"));
321	}
322	
323	#[test]
324	fn degenerate_props_draw_cleanly() {
325	    let cases = [
326	        ("line-chart", serde_json::json!({"values": "5"})),
327	        ("donut-chart", serde_json::json!({"values": "0, 0"})),
328	        ("gauge", serde_json::json!({"min": 0, "max": 0, "value": 0})),
329	    ];
330	    let mut failures = Vec::new();
331	    for (stem, overrides) in cases {
332	        let module = common::module(stem);
333	        let mut props = module.defaults();
334	        for (key, value) in overrides.as_object().unwrap() {
335	            props[key] = value.clone();
336	        }
337	        let d = duration(&module);
338	        for size in SIZES {
339	            for frame in [0, d / 2, d - 1] {
340	                if let Err(e) = draw(&module, frame, &props, size) {
341	                    failures.push(e);
342	                }
343	            }
344	        }
345	    }
346	    assert!(failures.is_empty(), "{}", failures.join("\n"));
347	}
348	
349	/// The file names listed under `key:` in the "Copy Graphic Templates" phase.
350	fn listed(phase: &str, key: &str) -> Vec<String> {
351	    let mut names: Vec<String> = phase
352	        .lines()
353	        .skip_while(|line| line.trim() != format!("{key}:"))
354	        .skip(1)
355	        .take_while(|line| line.trim_start().starts_with("- "))
356	        .map(|line| line.rsplit('/').next().unwrap().trim().to_string())
357	        .collect();
358	    names.sort();
359	    names
360	}
361	
362	#[test]
363	fn project_yml_lists_every_template() {
364	    let yml = fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../project.yml"))
365	        .expect("project.yml");
366	    let start = yml
367	        .find("- name: Copy Graphic Templates")
368	        .expect("the Copy Graphic Templates phase");
369	    let rest = &yml[start + 1..];
370	    let phase = &rest[..rest.find("- name:").unwrap_or(rest.len())];
371	    let mut files: Vec<String> = fs::read_dir(GRAPHICS)
372	        .expect("tests/graphics")
373	        .map(|entry| entry.expect("a directory entry").path())
374	        .filter(|path| path.extension().is_some_and(|ext| ext == "js"))
375	        .map(|path| path.file_name().unwrap().to_string_lossy().into_owned())
376	        .collect();
377	    files.sort();
378	    assert_eq!(listed(phase, "inputFiles"), files, "inputFiles");
379	    assert_eq!(listed(phase, "outputFiles"), files, "outputFiles");
380	}
