  1	// window-frame — a bundled template (spec §11 G-44): a window's chrome to
  2	// sit over a screen recording on the track beneath — a title bar with three
  3	// dots and a title (window) or an address field (browser), and a rounded
  4	// outline. The content area stays transparent.
  5	export const meta = {
  6	  name: "Window frame",
  7	  durationInFrames: 150,
  8	};
  9	
 10	export const schema = {
 11	  style:  { type: "enum",    default: "browser", options: ["browser", "window"] },
 12	  title:  { type: "string",  default: "Frame Job" },
 13	  url:    { type: "string",  default: "example.com" },
 14	  theme:  { type: "enum",    default: "dark", options: ["dark", "light"] },
 15	  scale:  { type: "number",  default: 0.86, min: 0.5, max: 1, step: 0.01 },
 16	  shadow: { type: "boolean", default: true },
 17	  accent: { type: "color",   default: "#ff5a36" },
 18	};
 19	
 20	export function render(frame, props, ctx) {
 21	  const u = Math.min(ctx.width, ctx.height) / 1080;
 22	  const D = ctx.durationInFrames;
 23	  const dark = props.theme !== "light";
 24	  const bar = dark ? "#2a2a31" : "#e9e9ee";
 25	  const edge = dark ? "#4a4a54" : "#c4c4cc";
 26	  const field = dark ? "#1b1b20" : "#ffffff";
 27	  const ink = dark ? "#e8e8ee" : "#2a2a31";
 28	  const faint = dark ? "#8a8a96" : "#8a8a96";
 29	  const scale = Math.max(0.5, Math.min(1, props.scale));
 30	  const safeW = ctx.width * 0.9;
 31	  const safeH = ctx.height * 0.9;
 32	  // The outline (2u, straddling the edge) stays inside title-safe even at scale 1.
 33	  const lw = 2 * u;
 34	  const w = Math.min(safeW * scale, safeW - 2 * lw);
 35	  const h = Math.min(safeH * scale, safeH - 2 * lw);
 36	  const x = (ctx.width - w) / 2;
 37	  const y = (ctx.height - h) / 2;
 38	  const r = 12 * u;
 39	  const barH = 64 * u;
 40	  const enter = spring({ frame, fps: ctx.fps, stiffness: 120, damping: 17 });
 41	  // The geometry never overshoots, so the window never grows past its settled size.
 42	  const settle = Math.min(1, enter);
 43	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 44	  const grow = 0.96 + 0.04 * settle;
 45	  const alpha = Math.max(0, Math.min(1, enter * 1.6)) * out;
 46	  const cx = ctx.width / 2;
 47	  const cy = ctx.height / 2;
 48	  // The shadow is kept inside title-safe: it is only as wide as the margin around the window allows.
 49	  const margin = Math.min((safeW - w) / 2, (safeH - h) / 2);
 50	  const blur = Math.min(26 * u, margin / 2.2);
 51	  // The rise is capped so the bottom edge, outline or shadow, never drops below title-safe while
 52	  // the window is still scaled down: (1 − settle)(rise − 0.02h) stays within the bottom margin.
 53	  const reach = Math.max(lw / 2, props.shadow && blur >= 1 ? blur * 1.6 : 0);
 54	  const riseMax = Math.max(0, Math.min(30 * u, 0.02 * h + (safeH - h) / 2 - reach));
 55	  const rise = (1 - settle) * riseMax;
 56	
 57	  let dots = "";
 58	  ["#ff5f57", "#febc2e", "#28c840"].forEach((colour, i) => {
 59	    const s = spring({ frame: frame - 8 - i * 4, fps: ctx.fps, stiffness: 260, damping: 12 });
 60	    if (s > 0.001) {
 61	      dots += `<circle cx="${x + 32 * u + i * 26 * u}" cy="${y + barH / 2}" r="${8 * u * s}" fill="${colour}" fill-opacity="${alpha}"/>`;
 62	    }
 63	  });
 64	  const uiFont = { family: "Source Sans 3", size: 26 * u, weight: 600 };
 65	  let middle = "";
 66	  const left = x + 130 * u;
 67	  const room = w - 2 * 130 * u;
 68	  if (props.style === "window") {
 69	    const size = Math.min(uiFont.size, fitText(props.title, room, uiFont, { min: 8 * u, max: uiFont.size }));
 70	    middle = `<text x="${cx}" y="${y + barH / 2 + size * 0.35}" text-anchor="middle" font-family="'Source Sans 3'"
 71	                    font-weight="600" font-size="${size}" fill="${ink}" fill-opacity="${alpha}">${escapeXml(props.title)}</text>`;
 72	  } else {
 73	    const fieldW = Math.min(room - 90 * u, Math.max(360 * u, w * 0.5));
 74	    const fieldH = 38 * u;
 75	    const fx = cx - fieldW / 2;
 76	    const fy = y + (barH - fieldH) / 2;
 77	    const size = Math.min(uiFont.size, fitText(props.url, fieldW - 90 * u, uiFont, { min: 8 * u, max: uiFont.size }));
 78	    const nav = (dx, dir) => {
 79	      const nx = left + dx;
 80	      const ny = y + barH / 2;
 81	      const k = 8 * u * dir;
 82	      return `<path d="M ${nx + k} ${ny - 8 * u} L ${nx - k} ${ny} L ${nx + k} ${ny + 8 * u}" fill="none" stroke="${faint}"
 83	                    stroke-opacity="${alpha}" stroke-width="${3 * u}" stroke-linecap="round" stroke-linejoin="round"/>`;
 84	    };
 85	    const lx = fx + 26 * u;
 86	    const ly = fy + fieldH / 2;
 87	    middle = `${nav(0, 1)}${nav(36 * u, -1)}
 88	      <rect x="${fx}" y="${fy}" width="${fieldW}" height="${fieldH}" rx="${fieldH / 2}" fill="${field}"
 89	            fill-opacity="${alpha}" stroke="${props.accent}" stroke-opacity="${alpha}" stroke-width="${2.5 * u}"/>
 90	      <rect x="${lx - 7 * u}" y="${ly - 3 * u}" width="${14 * u}" height="${11 * u}" rx="${2 * u}" fill="${faint}" fill-opacity="${alpha}"/>
 91	      <path d="M ${lx - 4.5 * u} ${ly - 3 * u} v ${-3 * u} a ${4.5 * u} ${4.5 * u} 0 0 1 ${9 * u} 0 v ${3 * u}" fill="none"
 92	            stroke="${faint}" stroke-opacity="${alpha}" stroke-width="${2 * u}"/>
 93	      <text x="${cx}" y="${ly + size * 0.35}" text-anchor="middle" font-family="'Source Sans 3'" font-weight="600"
 94	            font-size="${size}" fill="${ink}" fill-opacity="${alpha}">${escapeXml(props.url)}</text>`;
 95	  }
 96	  // A soft shadow of thin rings outside the outline, fading outward: a filter would cost ten
 97	  // times the frame budget, and a ring never darkens the transparent content area.
 98	  let shadow = "";
 99	  if (props.shadow && blur >= 1) {
100	    const rings = 12;
101	    const step = (blur * 1.6) / rings;
102	    for (let i = 0; i < rings; i++) {
103	      const o = (i + 0.5) * step;
104	      const fall = 1 - i / rings;
105	      shadow += `<rect x="${x - o}" y="${y - o}" width="${w + 2 * o}" height="${h + 2 * o}" rx="${r + o}" fill="none"
106	                       stroke="#000000" stroke-opacity="${0.16 * fall * fall * alpha}" stroke-width="${step}"/>`;
