108	  }
109	  // Opacity per element, so no frame isolates a window-sized layer.
110	  return svg(ctx, `
111	    <g transform="translate(${cx} ${cy + rise}) scale(${grow}) translate(${-cx} ${-cy})">
112	      ${shadow}
113	      <path d="M ${x} ${y + barH} v ${-(barH - r)} a ${r} ${r} 0 0 1 ${r} ${-r} h ${w - 2 * r} a ${r} ${r} 0 0 1 ${r} ${r}
114	               v ${barH - r} Z" fill="${bar}" fill-opacity="${alpha}"/>
115	      <line x1="${x}" y1="${y + barH}" x2="${x + w}" y2="${y + barH}" stroke="${edge}" stroke-opacity="${alpha}" stroke-width="${1.5 * u}"/>
116	      <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="none" stroke="${edge}" stroke-opacity="${alpha}" stroke-width="${lw}"/>
117	      ${dots}${middle}
118	    </g>`);
119	}

