  1	// countdown — a bundled template (spec §11 G-44): a timer counting from
  2	// `from` to `to` one step a second (up when `to` is greater), its digits
  3	// pulsing on each tick inside a ring that empties or fills, and a flash at
  4	// the end.
  5	export const meta = {
  6	  name: "Countdown",
  7	  durationInFrames: 330,
  8	};
  9	
 10	export const schema = {
 11	  from:   { type: "number",  default: 10 },
 12	  to:     { type: "number",  default: 0 },
 13	  format: { type: "enum",    default: "m:ss", options: ["seconds", "m:ss", "h:mm:ss"] },
 14	  label:  { type: "string",  default: "Starting in" },
 15	  ring:   { type: "boolean", default: true },
 16	  accent: { type: "color",   default: "#ff5a36" },
 17	};
 18	
 19	function clock(n, format) {
 20	  const sign = n < 0 ? "-" : "";
 21	  const s = Math.abs(n);
 22	  const two = (v) => String(v).padStart(2, "0");
 23	  if (format === "seconds") return sign + s;
 24	  if (format === "h:mm:ss") return `${sign}${Math.floor(s / 3600)}:${two(Math.floor(s / 60) % 60)}:${two(s % 60)}`;
 25	  return `${sign}${Math.floor(s / 60)}:${two(s % 60)}`;
 26	}
 27	
 28	export function render(frame, props, ctx) {
 29	  const u = Math.min(ctx.width, ctx.height) / 1080;
 30	  const D = ctx.durationInFrames;
 31	  const from = Math.round(props.from);
 32	  const to = Math.round(props.to);
 33	  const steps = Math.abs(to - from);
 34	  const t = Math.max(0, ctx.time);
 35	  const ticked = Math.min(steps, Math.floor(t));
 36	  const n = to < from ? from - ticked : from + ticked;
 37	  const done = t >= steps;
 38	  const cx = ctx.width / 2;
 39	  const cy = ctx.height / 2;
 40	  const R = 300 * u;
 41	  const thick = 22 * u;
 42	  const enter = spring({ frame, fps: ctx.fps, stiffness: 140, damping: 15 });
 43	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 44	  const local = t - Math.floor(t);
 45	  const pulse = done && t - steps > 0.3 ? 1 : interpolate(local, [0, 0.3], [1.08, 1], { easing: Easing.outCubic, clamp: true });
 46	  // From equal to `to` there is nothing to count: the ring stands at its end state and nothing flashes.
 47	  const left = steps === 0 ? 0 : Math.max(0, Math.min(1, 1 - t / steps));
 48	  const ringShown = to < from ? left : 1 - left;
 49	  const text = clock(n, props.format);
 50	  const widest = clock(from, props.format).length >= clock(to, props.format).length
 51	    ? clock(from, props.format) : clock(to, props.format);
 52	  const digitSize = fitText(widest.replace(/[0-9]/g, "0"), R * 1.45, { family: "IBM Plex Mono", weight: 500 },
 53	    { min: 12 * u, max: 190 * u });
 54	  const flash = done && steps > 0 ? interpolate(t - steps, [0, 0.6], [0.85, 0], { easing: Easing.outCubic, clamp: true }) : 0;
 55	  const labelText = props.label.toUpperCase();
 56	  const labelSize = fitText(labelText, R * 1.3, { family: "Montserrat", weight: 800, letterSpacing: 5 * u },
 57	    { min: 10 * u, max: 34 * u });
 58	  const circumference = 2 * Math.PI * R;
 59	  return svg(ctx, `
 60	    <g opacity="${out * Math.min(1, enter * 1.4)}"
 61	       transform="translate(${cx} ${cy}) scale(${0.85 + 0.15 * enter}) translate(${-cx} ${-cy})">
 62	      <circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="#101014" fill-opacity="0.82"/>
 63	      ${flash > 0 ? `<circle cx="${cx}" cy="${cy}" r="${R + thick / 2 + 8 * u}" fill="${props.accent}" fill-opacity="${flash}"/>` : ""}
 64	      ${props.ring ? `
 65	      <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.12" stroke-width="${thick}"/>
 66	      ${ringShown > 0.0005 ? `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${props.accent}"
 67	              stroke-width="${thick}" stroke-linecap="round" stroke-dasharray="${circumference * ringShown} ${circumference}"
 68	              transform="rotate(-90 ${cx} ${cy})"/>` : ""}` : ""}
 69	      <text x="${cx}" y="${cy - digitSize * 0.62}" text-anchor="middle" font-family="Montserrat" font-weight="800"
 70	            font-size="${labelSize}" letter-spacing="${5 * u}" fill="#d8d8e0">${escapeXml(labelText)}</text>
 71	      <g transform="translate(${cx} ${cy + digitSize * 0.12}) scale(${pulse})">
 72	        <text x="0" y="${digitSize * 0.35}" text-anchor="middle" font-family="IBM Plex Mono" font-weight="500"
 73	              font-size="${digitSize}" fill="#ffffff">${escapeXml(text)}</text>
 74	      </g>
 75	    </g>`);
 76	}
  1	// subscribe-button — a bundled template (spec §11 G-44): a pill button with
  2	// a play glyph pops in, a cursor glides to it and clicks (a squash and a
  3	// ripple), the button turns to its done state with a check, and a bell pops
  4	// in beside it and rings after a second click. Every glyph is a generic
  5	// vector shape.
  6	export const meta = {
  7	  name: "Subscribe button",
  8	  durationInFrames: 150,
  9	};
 10	
 11	export const schema = {
 12	  label:     { type: "string",  default: "SUBSCRIBE" },
 13	  doneLabel: { type: "string",  default: "SUBSCRIBED" },
 14	  bell:      { type: "boolean", default: true },
 15	  position:  { type: "enum",    default: "bottom", options: ["bottom", "center", "top"] },
 16	  accent:    { type: "color",   default: "#e5322d" },
 17	};
 18	
 19	const DONE = "#3a3a40";
 20	
 21	function bellPath(g) {
 22	  const s = (v) => v * g;
 23	  return `M ${s(-0.36)} ${s(0.26)} C ${s(-0.26)} ${s(0.14)} ${s(-0.28)} ${s(0.02)} ${s(-0.28)} ${s(-0.12)}
 24	    C ${s(-0.28)} ${s(-0.34)} ${s(-0.15)} ${s(-0.46)} 0 ${s(-0.46)} C ${s(0.15)} ${s(-0.46)} ${s(0.28)} ${s(-0.34)} ${s(0.28)} ${s(-0.12)}
 25	    C ${s(0.28)} ${s(0.02)} ${s(0.26)} ${s(0.14)} ${s(0.36)} ${s(0.26)} Z`;
 26	}
 27	
 28	export function render(frame, props, ctx) {
 29	  const u = Math.min(ctx.width, ctx.height) / 1080;
 30	  const D = ctx.durationInFrames;
 31	  const safeY = ctx.height * 0.05;
 32	  const safeW = ctx.width * 0.9;
 33	  const safeH = ctx.height * 0.9;
 34	  const click = Math.round(D * 0.4);
 35	  const done = frame >= click + 3;
 36	  const btnH = 96 * u;
 37	  const font = { family: "Montserrat", size: 38 * u, weight: 900, letterSpacing: 2 * u };
 38	  const room = safeW - 2 * 60 * u - (props.bell ? btnH + 24 * u : 0) - btnH * 1.1;
 39	  const sizeOf = (t) => Math.min(font.size, fitText(t, room, font, { min: 10 * u, max: font.size }));
 40	  const widthOf = (t, size) => measureText(t, Object.assign({}, font, { size })).width;
 41	  const sizeA = sizeOf(props.label);
 42	  const sizeB = sizeOf(props.doneLabel);
 43	  const wA = btnH * 0.95 + widthOf(props.label, sizeA) + 44 * u;
 44	  const wB = btnH * 0.95 + widthOf(props.doneLabel, sizeB) + 44 * u;
 45	  const morph = interpolate(frame, [click + 2, click + 12], [0, 1], { easing: Easing.inOutCubic, clamp: true });
 46	  const btnW = wA + (wB - wA) * morph;
 47	  const bellD = btnH;
 48	  const groupW = Math.max(wA, wB) + (props.bell ? 24 * u + bellD : 0);
 49	  const margin = 70 * u;
 50	  const cy = props.position === "top" ? safeY + margin + btnH / 2
 51	    : props.position === "center" ? ctx.height / 2
 52	    : safeY + safeH - margin - btnH / 2 - 40 * u;
 53	  const gx = ctx.width / 2 - groupW / 2;
 54	  const bx = gx;
 55	  const bcx = bx + btnW / 2;
 56	  const pop = spring({ frame, fps: ctx.fps, stiffness: 180, damping: 12 });
 57	  const squash = interpolate(frame, [click - 2, click + 1, click + 7], [1, 0.94, 1], { clamp: true });
 58	  const out = interpolate(frame, [D - 15, D - 1], [0, 1], { easing: Easing.inCubic, clamp: true });
 59	  const fill = done ? DONE : props.accent;
 60	  const label = done ? props.doneLabel : props.label;
 61	  const size = done ? sizeB : sizeA;
 62	  const ix = bx + btnH * 0.55;
 63	  const g = btnH * 0.42;
 64	  const icon = done
 65	    ? `<path d="M ${ix - g * 0.38} ${cy} L ${ix - g * 0.1} ${cy + g * 0.28} L ${ix + g * 0.4} ${cy - g * 0.3}" fill="none"
 66	             stroke="#ffffff" stroke-width="${7 * u}" stroke-linecap="round" stroke-linejoin="round"/>`
 67	    : `<path d="M ${ix - g * 0.3} ${cy - g * 0.42} L ${ix + g * 0.45} ${cy} L ${ix - g * 0.3} ${cy + g * 0.42} Z" fill="#ffffff"
 68	             stroke="#ffffff" stroke-width="${4 * u}" stroke-linejoin="round"/>`;
 69	  // The click lands on the button's right end, past the label's last letter in either state, so
 70	  // the cursor never covers the label; it rides that end as the button grows to its done label.
 71	  const target1x = bx + btnW - btnH * 0.3;
 72	  const ripple = interpolate(frame, [click, click + 16], [0, 1], { easing: Easing.outCubic, clamp: true });
 73	  const rippleOn = frame >= click && ripple < 1;
 74	  const button = `
 75	    <clipPath id="pill"><rect x="${bx}" y="${cy - btnH / 2}" width="${btnW}" height="${btnH}" rx="${btnH / 2}"/></clipPath>
 76	    <g transform="translate(${bcx} ${cy}) scale(${squash}) translate(${-bcx} ${-cy})">
 77	      <rect x="${bx}" y="${cy - btnH / 2}" width="${btnW}" height="${btnH}" rx="${btnH / 2}" fill="${fill}"/>
 78	      ${rippleOn ? `<g clip-path="url(#pill)"><circle cx="${target1x}" cy="${cy}" r="${btnW * ripple}"
 79	          fill="#ffffff" fill-opacity="${0.35 * (1 - ripple)}"/></g>` : ""}
 80	      ${icon}
 81	      <text x="${bx + btnH * 0.95}" y="${cy + size * 0.36}" font-family="Montserrat" font-weight="900" font-size="${size}"
 82	            letter-spacing="${2 * u}" fill="#ffffff">${escapeXml(label)}</text>
 83	    </g>`;
 84	
 85	  // The bell pops in after the first click, the cursor clicks it, and it rings.
 86	  const bellX = bx + Math.max(wA, wB) + 24 * u + bellD / 2;
 87	  const click2 = click + 26;
 88	  let bell = "";
 89	  if (props.bell) {
 90	    const bpop = spring({ frame: frame - click - 8, fps: ctx.fps, stiffness: 200, damping: 11 });
 91	    const t = (frame - click2) / ctx.fps;
 92	    const ring = frame >= click2 ? 18 * Math.exp(-3 * t) * Math.sin(t * 2 * Math.PI * 3.2) : 0;
 93	    const on = frame >= click2;
 94	    if (bpop > 0.001) {
 95	      const bg = bellD * 0.62;
 96	      bell = `<g transform="translate(${bellX} ${cy}) scale(${bpop})">
 97	        <circle cx="0" cy="0" r="${bellD / 2}" fill="${on ? props.accent : DONE}"/>
 98	        <g transform="translate(0 ${-bg * 0.08}) rotate(${ring} 0 ${-bg * 0.46})">
 99	          <path d="${bellPath(bg)}" fill="#ffffff"/>
100	          <circle cx="0" cy="${bg * 0.36}" r="${bg * 0.1}" fill="#ffffff"/>
101	          <circle cx="0" cy="${-bg * 0.5}" r="${bg * 0.07}" fill="#ffffff"/>
102	        </g></g>`;
103	    }
104	  }
105	
106	  // The cursor: from the lower right inside title-safe, to the button's right end, then the bell.
107	  const target2x = bellX + bellD * 0.1;
108	  const tipY = cy + btnH * 0.12;
109	  const startX = Math.min(ctx.width * 0.95 - 120 * u, bx + wA - btnH * 0.3 + 380 * u);
110	  const startY = Math.min(ctx.height * 0.95 - 120 * u, cy + 150 * u);
111	  const glide = interpolate(frame, [10, click - 4], [0, 1], { easing: Easing.inOutCubic, clamp: true });
112	  const hop = interpolate(frame, [click + 10, click2 - 4], [0, 1], { easing: Easing.inOutCubic, clamp: true });
113	  let curX = startX + (target1x - startX) * glide;
114	  let curY = startY + (tipY - startY) * glide;
115	  if (props.bell) {
116	    curX += (target2x - target1x) * hop;
117	    curY += -12 * u * Math.sin(Math.PI * hop);
118	  }
