120	    : props.bell && frame >= click2 - 2 && frame < click2 + 4 ? 0.88 : 1;
121	  const curIn = interpolate(frame, [8, 16], [0, 1], { clamp: true });
122	  const k = 46 * u;
123	  const cursor = curIn > 0 ? `<g transform="translate(${curX} ${curY}) scale(${press})" opacity="${curIn}">
