125	               L ${k * 0.4} ${k * 0.71} L ${k * 0.72} ${k * 0.71} Z" fill="#ffffff" stroke="#111114"
126	            stroke-width="${3 * u}" stroke-linejoin="round"/>
127	    </g>` : "";
128	  const gcx = ctx.width / 2;
129	  const scale = pop * (1 - 0.15 * out);
130	  return svg(ctx, `
131	    <g opacity="${1 - out}" transform="translate(${gcx} ${cy}) scale(${scale}) translate(${-gcx} ${-cy})">
132	      ${button}${bell}${cursor}
133	    </g>`);
134	}

