  1	// end-screen — a bundled template (spec §11 G-44): a full card laid out for
  2	// a video's end screen — two 16:9 placeholders where the platform's video
  3	// elements go and a subscribe circle — the two side by side with the circle
  4	// centred under them in landscape and square, a column in portrait, under a title.
  5	export const meta = {
  6	  name: "End screen",
  7	  durationInFrames: 300,
  8	};
  9	
 10	export const schema = {
 11	  title:      { type: "string", default: "Watch next" },
 12	  videoA:     { type: "string", default: "Latest video" },
 13	  videoB:     { type: "string", default: "Best for you" },
 14	  subscribe:  { type: "string", default: "Subscribe" },
 15	  background: { type: "color",  default: "#0b0b10" },
 16	  accent:     { type: "color",  default: "#ff5a36" },
