 22	    <path d="M ${cx - r} ${cy} C ${cx - r} ${cy - r * 2.2} ${cx + r * 0.2} ${y + s * 0.08} ${cx + r * 1.25} ${y}
 23	             L ${cx + r * 1.25} ${y + s * 0.18} C ${cx + r * 0.25} ${y + s * 0.3} ${cx - r * 0.15} ${cy - r * 1.3} ${cx + r * 0.2} ${cy - r * 0.95} Z"/>`;
 24	}
