 26	export function render(frame, props, ctx) {
 27	  const u = Math.min(ctx.width, ctx.height) / 1080;
 28	  const D = ctx.durationInFrames;
 29	  const safeY = ctx.height * 0.05;
 30	  const safeW = ctx.width * 0.9;
 31	  const safeH = ctx.height * 0.9;
