 65	  const attrY = top + markH + 50 * u + lines.length * lineH + 60 * u + 40 * u;
 66	  const slide = (1 - attrIn) * -40 * u;
 67	  const attrText = props.attribution.trim() ? `— ${props.attribution}` : "";
 68	  const attrFit = attrText ? Math.min(attrSize, fitText(attrText, textW,
 69	    { family: "Montserrat", weight: 800 }, { min: 10 * u, max: attrSize })) : attrSize;
 70	  return svg(ctx, `
 71	    ${markIn > 0.001 ? `<g fill="${props.accent}" fill-opacity="${out}"
 72	       transform="translate(${mcx} ${mcy}) scale(${markIn}) translate(${-mcx} ${-mcy})">
 73	      ${mark(mx, my, markH)}${mark(mx + markH * 0.72, my, markH)}
 74	    </g>` : ""}
 75	    ${body}
 76	    ${attrIn > 0 ? `<rect x="${left + slide}" y="${attrY - attrSize - 34 * u}" width="${80 * u}" height="${6 * u}"
 77	          fill="${props.accent}" fill-opacity="${attrIn * out}"/>
 78	    <text x="${left + slide}" y="${attrY}" font-family="Montserrat" font-weight="800"
 79	          font-size="${attrFit}" fill="#d8d8e0" fill-opacity="${attrIn * out}">${escapeXml(attrText)}</text>` : ""}`,
 80	    { background: props.background });
 81	}

content.content:
  1	// donut-chart — a bundled template (spec §11 G-44): `values` as a
  2	// comma-separated string, slices sweeping clockwise in turn, the first
  3	// slice's share counting up in the centre and a staggered legend.
  4	export const meta = {
  5	  name: "Donut chart",
  6	  durationInFrames: 150,
  7	};
  8	
  9	export const schema = {
 10	  values: { type: "string", default: "45, 30, 15, 10", animate: false },
 11	  labels: { type: "string", default: "Video, Audio, Graphics, Other", animate: false },
 12	  title:  { type: "string", default: "Where the time goes" },
 13	  accent: { type: "color",  default: "#ff5a36" },
 14	};
 15	
 16	const PALETTE = ["#2d7ff9", "#ffd60a", "#34c759", "#af52de", "#ff9f0a", "#5ac8fa"];
 17	
 18	// An arc of the circle (cx, cy, r) from angle a0 to a1, in degrees clockwise
 19	// from twelve o'clock; a full turn is two half arcs.
 20	function arc(cx, cy, r, a0, a1) {
 21	  const at = (a) => {
 22	    const t = ((a - 90) * Math.PI) / 180;
 23	    return `${cx + r * Math.cos(t)} ${cy + r * Math.sin(t)}`;
 24	  };
 25	  if (a1 - a0 >= 359.99) {
 26	    return `M ${at(a0)} A ${r} ${r} 0 1 1 ${at(a0 + 180)} A ${r} ${r} 0 1 1 ${at(a0 + 359.99)}`;
 27	  }
 28	  return `M ${at(a0)} A ${r} ${r} 0 ${a1 - a0 > 180 ? 1 : 0} 1 ${at(a1)}`;
 29	}
 30	
 31	export function render(frame, props, ctx) {
 32	  const u = Math.min(ctx.width, ctx.height) / 1080;
 33	  const D = ctx.durationInFrames;
 34	  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v))
 35	    .map((v) => Math.max(0, v));
 36	  const labels = props.labels.split(",").map((l) => l.trim());
 37	  const n = values.length;
 38	  const total = values.reduce((a, b) => a + b, 0);
 39	  // A square frame takes the side-by-side layout: a column would not fit its height.
 40	  const landscape = ctx.width >= ctx.height;
 41	  const safeX = ctx.width * 0.05;
 42	  const safeY = ctx.height * 0.05;
 43	  const safeW = ctx.width * 0.9;
 44	  const safeH = ctx.height * 0.9;
 45	  const pad = 60 * u;
 46	  const innerW = safeW - 2 * pad;
 47	  const titleSize = fitText(props.title, innerW, { family: "Montserrat", weight: 900 }, { min: 12 * u, max: 64 * u });
 48	  const rowH = Math.min(78 * u, (landscape ? safeH - 300 * u : 560 * u) / Math.max(1, n));
 49	  const legendH = rowH * n;
 50	  const thick = 64 * u;
 51	  let legendW = Math.min(620 * u, innerW);
 52	  let R;
 53	  let cx;
 54	  let cy;
 55	  let legendX;
 56	  let legendY;
 57	  let blockTop;
 58	  if (landscape) {
 59	    // The donut leaves the legend at least 360u beside it (a square frame's narrow width).
 60	    const gapL = Math.min(140 * u, innerW * 0.1);
 61	    R = Math.min((safeH - 2 * pad - titleSize - 100 * u) / 2 - thick / 2, innerW * 0.22,
 62	      (innerW - thick - gapL - 360 * u) / 2);
 63	    legendW = Math.min(620 * u, innerW - 2 * R - thick - gapL);
 64	    blockTop = safeY + Math.max(pad, (safeH - (titleSize + 70 * u + 2 * R + thick)) / 2);
 65	    const blockW = 2 * R + thick + gapL + legendW;
 66	    cx = Math.max(safeX + pad, (ctx.width - blockW) / 2) + thick / 2 + R;
 67	    cy = blockTop + titleSize + 70 * u + thick / 2 + R;
 68	    legendX = cx + R + thick / 2 + gapL;
 69	    legendY = cy - legendH / 2;
 70	  } else {
 71	    R = innerW * 0.3;
 72	    const blockH = titleSize + 80 * u + 2 * R + thick + 90 * u + legendH;
 73	    blockTop = safeY + Math.max(pad, (safeH - blockH) / 2);
 74	    cx = ctx.width / 2;
 75	    cy = blockTop + titleSize + 80 * u + thick / 2 + R;
 76	    legendX = (ctx.width - legendW) / 2;
 77	    legendY = cy + R + thick / 2 + 90 * u;
 78	  }
 79	  const titleX = landscape ? cx - R - thick / 2 : ctx.width / 2;
 80	  const titleFits = landscape
 81	    ? Math.min(titleSize, fitText(props.title, safeX + safeW - pad - titleX, { family: "Montserrat", weight: 900 },
 82	      { min: 12 * u, max: 64 * u }))
 83	    : titleSize;
 84	  const fade = interpolate(frame, [0, 15], [0, 1], { clamp: true });
 85	  const out = interpolate(frame, [D - 15, D - 1], [1, 0], { clamp: true });
 86	  const sweep = interpolate(frame, [8, 70], [0, 360], { easing: Easing.inOutCubic, clamp: true });
 87	  const gap = n > 1 ? 1.6 : 0;
 88	
 89	  let slices = `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#ffffff" stroke-opacity="0.08"
 90	                        stroke-width="${thick}"/>`;
 91	  let start = 0;
 92	  values.forEach((v, i) => {
 93	    const size = total > 0 ? (v / total) * 360 : 0;
 94	    const shown = Math.min(sweep, start + size) - start;
 95	    if (size > 0 && shown > gap) {
 96	      const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
 97	      slices += `<path d="${arc(cx, cy, R, start + gap / 2, start + shown - gap / 2)}" fill="none"
 98	                       stroke="${colour}" stroke-width="${thick}"/>`;
 99	    }
100	    start += size;
101	  });
102	
103	  const share = total > 0 ? (values[0] / total) * 100 : 0;
104	  const counted = share * interpolate(frame, [8, 70], [0, 1], { easing: Easing.inOutCubic, clamp: true });
105	  const percentSize = Math.min(120 * u, R * 0.62);
106	  const centre = `
107	    <text x="${cx}" y="${cy + percentSize * 0.3}" text-anchor="middle" font-family="IBM Plex Mono"
108	          font-weight="500" font-size="${percentSize}" fill="#ffffff">${Math.round(counted)}%</text>
109	    <text x="${cx}" y="${cy + percentSize * 0.3 + 52 * u}" text-anchor="middle" font-family="Montserrat"
110	          font-weight="800" font-size="${28 * u}" fill="#c8c8d0" opacity="${fade}">${escapeXml(labels[0] || "")}</text>`;
111	
112	  let legend = "";
113	  const legendFont = { family: "Montserrat", size: Math.min(36 * u, rowH * 0.5), weight: 800 };
114	  values.forEach((v, i) => {
115	    const t = spring({ frame: frame - 24 - i * 6, fps: ctx.fps, damping: 16 });
116	    if (t <= 0.001) return;
117	    const colour = i === 0 ? props.accent : PALETTE[(i - 1) % PALETTE.length];
118	    const y = legendY + rowH * i + rowH / 2;
119	    const pct = total > 0 ? `${Math.round((v / total) * 100)}%` : "0%";
120	    const sq = legendFont.size * 0.8;
121	    legend += `<g opacity="${Math.min(1, t)}" transform="translate(${(1 - Math.min(1, t)) * 30 * u} 0)">
122	      <rect x="${legendX}" y="${y - sq / 2}" width="${sq}" height="${sq}" rx="${sq * 0.2}" fill="${colour}"/>
123	      <text x="${legendX + sq + 22 * u}" y="${y + legendFont.size * 0.36}" font-family="Montserrat" font-weight="800"
124	            font-size="${legendFont.size}" fill="#ffffff">${escapeXml(labels[i] || "")}</text>
125	      <text x="${legendX + legendW}" y="${y + legendFont.size * 0.36}" text-anchor="end" font-family="IBM Plex Mono"
126	            font-weight="500" font-size="${legendFont.size}" fill="#c8c8d0">${pct}</text></g>`;
127	  });
128	
129	  return svg(ctx, `
130	    <g opacity="${out}">
131	      <text x="${titleX}" y="${blockTop + titleSize * 0.8}" text-anchor="${landscape ? "start" : "middle"}"
132	            font-family="Montserrat" font-weight="900" font-size="${titleFits}" fill="#ffffff"
133	            opacity="${fade}">${escapeXml(props.title)}</text>
134	      ${slices}${centre}${legend}
135	    </g>`, { background: "#15151b" });
136	}

